progress {
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  height: 5px;
  border: 0;
  z-index: 100;
}

/* dwv */
.dwv {
  display: flex;
  flex-direction: column;
}
.layerGroup {
  position: relative;
  padding: 0;
  display: flex;
  justify-content: center;
  /* occupy space left by panel */
  flex: 1;
  min-height: 0;
  min-width: 0;
}
.layer {
  position: absolute;
  pointer-events: none;
}

/* Info layer */
.infoLayer {
  position: absolute;
  pointer-events: none;
  z-index: 5;
  width: 100%;
  height: 100%;
}
.infoLayer ul {
  margin: 0;
  padding: 2px;
  list-style-type: none;
}
.infoLayer li {
  margin-top: 0;
}
.infoLayer canvas {
  margin: 0;
  padding: 2px;
}
.info {
  font-size: 80%;
  max-width: 50%;
  max-height: 50%;
  overflow: auto;
}
/* position indicators (c, tl, tc, bl...)
  need to be in sync with those defined
  in the overlay.json file */
/* center */
.info-c {
  font-size: 120%;
}
/* top left */
.info-tl {
  position: absolute;
  top: 0;
  left: 0;
  text-align: left;
}
/* top center */
.info-tc {
  position: absolute;
  top: 0;
  left: 50%;
  right: 50%;
  text-align: center;
}
/* top right */
.info-tr {
  position: absolute;
  top: 0;
  right: 0;
  text-align: right;
}
/* center left */
.info-cl {
  position: absolute;
  bottom: 50%;
  left: 0;
  text-align: left;
}
/* center right */
.info-cr {
  position: absolute;
  bottom: 50%;
  right: 2px;
  text-align: right;
}
/* bottom left */
.info-bl {
  position: absolute;
  bottom: 0;
  left: 0;
  text-align: left;
}
/* bottom center */
.info-bc {
  position: absolute;
  bottom: 0;
  left: 50%;
  right: 50%;
  text-align: center;
}
/* bottom right */
.info-br {
  position: absolute;
  bottom: 0;
  right: 0;
  text-align: right;
}

/* drag&drop */
.dropBox {
  text-align: center;
  width: 50%;
}
.dropBoxBorder {
  margin: 20px auto;
  border-width: 5px;
  border-style: dashed;
}
.input-file-link {
  text-decoration-line: underline;
}

button svg {
  /* avoid pointer events to let parent be target */
  pointer-events: none;
}

/* content */
.content {
  /* occupy space left by header and footer */
  flex: 1;
  min-height: 0;

  display: flex;
}

/* header */
.header {
  font: 14px arial, sans-serif;
  margin-bottom: 5px;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
}
.toolbar-item {
  margin: 10px 3px;
  height: 40px;

  display: flex;
  align-items: center;
  gap: 0;
}
.toolbar-item button {
  height: 100%;
  border-radius: 4px;
  padding: 10px;
}

/* select-wraper */
.select-wrapper {
  height: 100%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.select-wrapper select {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  appearance: none;
  -webkit-appearance: none;
}
.select-wrapper button {
  padding: 0;
  margin: 0 0 0 1px;
}
.select-wrapper select:enabled:hover {
  cursor: pointer;
}

input[type=color] {
  width: 27px;
  height: 27px;

  border-width: 0;
}

button {
  border-width: 0;
}
button:enabled:hover {
  cursor: pointer;
}

/* footer */
.footer {
  text-align: center;
  font-size: 8pt;
  margin: 1em;
}

/* right panel (see doc/design/rightPanel.md) */
.right-panel-toggle-strip {
  flex: none;
  padding: 4px 2px 0 2px;
  border-left: 1px solid;
}
.right-panel-toggle-strip[hidden] {
  display: none;
}
.right-panel {
  flex: none;
  position: relative;
  width: 0;
  border-left: 0 solid;
  /* clip, not hidden: focus cannot scroll it and hide the handle */
  overflow: clip;
}
.right-panel.open {
  border-left-width: 1px;
}
.right-panel.resizing {
  user-select: none;
}
.right-panel-resize-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 6px;
  z-index: 1;
  cursor: col-resize;
  touch-action: none;
  outline: none;
}
.right-panel-content {
  height: 100%;
  display: flex;
  flex-direction: column;
}
.right-panel-header {
  padding: 4px 2px 0 0;
  display: flex;
  justify-content: flex-end;
}
.right-panel-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 0 8px 8px 8px;
}
/* icon button: 24px hit area, 18px icon */
.right-panel-toggle {
  width: 24px;
  height: 24px;
  padding: 0;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  svg {
    width: 18px;
    height: 18px;
  }
}

/* right panel content (see doc/design/annotationComponent.md) */
.data-list {
  list-style-type: none;
  margin: 0;
  padding: 5px;
  /* medium body text */
  font: 400 14px/20px arial, sans-serif;

  .data-item + .data-item {
    margin-top: 8px;
  }
  .data-item-header {
    display: flex;
    align-items: center;
    .data-item-name {
      flex: 1;
      /* large label text */
      font-size: 14px;
      line-height: 20px;
      font-weight: 500;
    }
  }

  /* icon buttons: 28px hit area, 18px icon */
  .data-item-actions,
  .data-item-list-item-actions {
    display: flex;
    align-items: center;
    button {
      width: 28px;
      height: 28px;
      padding: 0;
      border-radius: 50%;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      svg {
        width: 18px;
        height: 18px;
      }
    }
    /* colour swatch */
    input[type=color] {
      width: 20px;
      height: 20px;
      margin: 0 4px;
      padding: 0;
      border: 0;
      cursor: pointer;
    }
    input[type=color]::-webkit-color-swatch-wrapper {
      padding: 0;
    }
    input[type=color]::-webkit-color-swatch {
      border: 0;
      border-radius: 2px;
    }
    input[type=color]::-moz-color-swatch {
      border: 0;
      border-radius: 2px;
    }
    input[type=color]:disabled {
      cursor: default;
      opacity: 0.38;
    }
  }
}
.data-item-list {
  list-style-type: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.data-item-list-item {
  padding-left: 8px;
  border-radius: 4px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}
/* row content: shape icon and label */
.data-item-list-item-content {
  flex: 1;
  min-width: 0;
  padding: 0;
  border: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  font: inherit;
  text-align: left;
  .shape-icon {
    flex-shrink: 0;
    width: 18px;
    height: 18px;
  }
}
.data-item-list-item-content:enabled:hover {
  /* hover is shown by the row */
  filter: none;
}
.data-item-list-item-label {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.data-item-list-item-label.not-viewable {
  text-decoration-line: line-through;
}
.data-item-list-empty {
  padding-left: 8px;
  font-style: italic;
}
.data-item-list-item-details {
  flex-basis: 100%;
  margin: 0 8px 4px 0;
  padding-top: 4px;
  border-top: 1px solid;
  /* small body text */
  font-size: 12px;
  line-height: 16px;

  /* group title and values on one line, wrap if needed */
  .quantification-group {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    column-gap: 1em;
    row-gap: 2px;
    margin-top: 3px;
  }
  .quantification-group:first-child {
    margin-top: 0;
  }
  .quantification-title {
    /* medium label text */
    font-size: 12px;
    line-height: 16px;
    font-weight: 500;
  }
  /* pairs flow in the group line (avoids the title alone on a line) */
  .quantification {
    display: contents;
    div {
      display: flex;
      align-items: baseline;
      gap: 0.3em;
    }
    dt {
      opacity: 0.7;
      font-size: 0.9em;
    }
    dd {
      margin: 0;
      white-space: nowrap;
      font-variant-numeric: tabular-nums;
    }
  }
  .quantification-empty {
    font-style: italic;
  }
}

/* snackbar */
.dwv {
  position: relative;
}
.snackbar {
  position: absolute;
  left: 50%;
  bottom: 16px;
  transform: translateX(-50%);
  z-index: 20;
  max-width: 80%;
  padding: 14px 16px;
  border-radius: 4px;
  font: 400 14px/20px arial, sans-serif;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
}

/* modal dialog */
.modal {
  display: none; /* Hidden by default */
  position: fixed; /* Stay in place */
  z-index: 10; /* Sit on top */
  left: 0;
  top: 0;
  width: 100%; /* Full width */
  height: 100%; /* Full height */

  .modal-content {
    /* size and position */
    box-sizing: border-box;
    width: 60%;
    min-width: min(400px, 95%);
    max-width: 900px;
    height: 70%;
    margin: 10vh auto;
    padding: 20px;
    /* title and controls on top, scrollable part takes the rest */
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  h2 {
    margin-top: 0;
  }

  input, label {
    vertical-align: middle;
    margin-right: 10px;
  }

  .tags-controls {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 5px;
    margin-bottom: 10px;
  }
  .tags-search {
    flex: 1;
    min-width: 150px;
  }

  .modal-content-scroll {
    flex: 1;
    min-height: 0;
    overflow: auto;

    table {
      width: 100%;
      border-collapse: collapse;
    }
    th {
      position: sticky;
      top: 0;
      text-align: left;
      border-bottom: 2px solid;
    }
    td {
      border-bottom: thin solid;
      vertical-align: top;
    }
    td, th {
      padding: 6px 10px;
    }
    /* name column */
    td:first-child {
      width: 35%;
      font-weight: 500;
    }
    /* value column: wrap long values (UIDs, arrays) */
    td:last-child {
      font-family: monospace;
      overflow-wrap: anywhere;
    }
  }
}
