:host {
  /* surface: main background */
  --surface: #1a1c1e;
  /* text and icons on any surface */
  --on-surface: #e2e2e6;
  /* surface container: panels, dialogs */
  --surface-container: #2d3033;
  /* surface container high: elements on top of surface container */
  --surface-container-high: #43474e;
  /* primary: buttons */
  --primary: #ffabf3;
  --on-primary: #5b005b;
  /* primary container: selected buttons, pressed toggles */
  --primary-container: #810081;
  --on-primary-container: #ffd7f5;
  /* secondary container: selected list items */
  --secondary-container: #5d3f57;
  --on-secondary-container: #ffd7f2;
  /* on surface variant: secondary text */
  --on-surface-variant: #c4c7c5;
  /* inverse surface: snackbar */
  --inverse-surface: #e2e2e6;
  --inverse-on-surface: #2f3033;
  /* outline: borders */
  --outline: #333;
  /* outline variant: decorative borders (panel) */
  --outline-variant: #44474f;
}
