import {Toolbar} from './lib/toolbar.js';
import {RightPanel} from './lib/rightPanel.js';

/**
 * @import {DwvAppService} from './lib/dwvAppService.js';
 * @import {AnnotationService} from './lib/annotationService.js';
 */

/**
 * Get the dwv div id.
 *
 * @param {string} viewerId The viewer id.
 * @returns {string} The id.
 */
export function getDwvDivId(viewerId) {
  return viewerId + '-dwv';
};

/**
 * Get the layer group div id.
 *
 * @param {string} viewerId The viewer id.
 * @returns {string} The id.
 */
export function getLayerGroupDivId(viewerId) {
  return viewerId + '-layerGroup';
};

/**
 * Get the header div id.
 *
 * @param {string} viewerId The viewer id.
 * @returns {string} The id.
 */
export function getHeaderDivId(viewerId) {
  return viewerId + '-header';
};

/**
 * GUI class.
 */
export class Gui {

  /**
   * The viewer id.
   *
   * @type {string}
   */
  #viewerId;

  /**
   * The root document.
   *
   * @type {Document}
   */
  #rootDoc;

  /**
   * The toolbar.
   *
   * @type {Toolbar}
   */
  #toolbar;

  /**
   * The right panel.
   *
   * @type {RightPanel}
   */
  #rightPanel;

  /**
   * @param {DwvAppService} dwvAppService The dwv app service.
   * @param {AnnotationService} annotService The annotation service.
   * @param {string[]} optionGuiTools The list of gui tools.
   */
  constructor(dwvAppService, annotService, optionGuiTools) {
    this.#viewerId = dwvAppService.getOptions().viewerId;
    this.#rootDoc = dwvAppService.getOptions().rootDocument;

    this.#toolbar = new Toolbar(dwvAppService, optionGuiTools);
    this.#rightPanel = new RightPanel(dwvAppService, annotService);

    dwvAppService.addEventListener('loadprogress', (event) => {
      this.setProgress(event.detail.value);
    });
  };

  /**
   * Initialise the GUI.
   */
  init() {
    this.#toolbar.init();
    this.#rightPanel.init();
  };

  /**
   * Get the toolbar.
   *
   * @returns {Toolbar} The toolbar.
   */
  getToolbar() {
    return this.#toolbar;
  }

  /**
   * Get the dwv div id.
   *
   * @returns {string} The id.
   */
  #getProgressDivId() {
    return this.#viewerId + '-progress';
  };

  /**
   * Set the progress: add if not present, update value,
   *   hide if percent is 100.
   *
   * @param {number} percent The progess percent.
   */
  setProgress(percent) {
    let progressDiv = this.#rootDoc.getElementById(
      this.#getProgressDivId());
    // create if not present
    if (!progressDiv) {
      progressDiv = document.createElement('progress');
      progressDiv.id = this.#getProgressDivId();
      progressDiv.max = '100';
      progressDiv.value = '0';
      // add as first header child
      const header = this.#rootDoc.getElementById(
        getHeaderDivId(this.#viewerId));
      header.insertBefore(progressDiv, header.firstChild);
    }
    // remove or update value
    if (percent === 100) {
      progressDiv.remove();
    } else {
      progressDiv.value = percent;
    }
  };

}; // class Gui
