.dwv {
  background-color: var(--surface);
  color: var(--on-surface)
}

/* svg */
path {
  fill: var(--on-surface);
}

/* footer */
.footer a {
  color: var(--on-surface);
}

/* info layer */
.info {
  color: #cde;
  text-shadow: 1px 1px #000;
}
/* position indicators (c, tl, tc, bl...)
  need to be in sync with those defined
  in the overlay.json file */
/* center */
.info-c {
  color: #ff0;
  text-shadow: 1px 1px #000;
}

/* drag&drop */
.dropBoxBorder {
  border-color: var(--outline);
}
.dropBoxBorder:hover {
  filter: brightness(150%);
}

/* button/input */
input[type=color] {
  background-color: var(--primary);
  color: var(--on-primary);
}
button path {
  fill: var(--on-primary);
}
button {
  background-color: var(--primary);
  color: var(--on-primary);
}
button.active {
  background-color: var(--primary-container);
}
button:enabled path {
  fill: var(--on-primary);
}
button:enabled:hover {
  filter: brightness(var(--hover-brightness, 120%));
}
button:disabled {
  filter: brightness(var(--disabled-brightness, 80%));
}
button:disabled path {
  filter: brightness(var(--disabled-icon-brightness, 80%));
}
button.active:enabled path {
  fill: var(--on-primary-container);
}

/* right panel */
.right-panel-toggle-strip,
.right-panel {
  background-color: var(--surface-container,
    color-mix(in srgb, var(--on-surface) 12%, transparent));
  color: var(--on-surface);
  border-color: var(--outline-variant);
}
.right-panel-resize-handle {
  background-color: transparent;
}
.right-panel-resize-handle:hover,
.right-panel-resize-handle:focus,
.right-panel.resizing .right-panel-resize-handle {
  background-color: var(--primary);
}
/* toggle: transparent icon button, state layer on hover */
.right-panel-toggle {
  background-color: transparent;
}
.right-panel-toggle:enabled:hover {
  filter: none;
  background-color: color-mix(
    in srgb, var(--on-surface) 8%, transparent);
}
.right-panel-toggle:enabled path {
  fill: var(--on-surface);
}

/* right panel content */
.data-item-name {
  color: var(--on-surface);
}
/* icon buttons: transparent, state layer on hover */
.data-item-actions button,
.data-item-list-item-actions button {
  background-color: transparent;
}
.data-item-actions button:enabled:hover,
.data-item-list-item-actions button:enabled:hover {
  filter: none;
  background-color: color-mix(
    in srgb, var(--on-surface) 8%, transparent);
}
.data-item-actions button:enabled path,
.data-item-list-item-actions button:enabled path {
  fill: var(--on-surface);
}
/* toggle on */
.data-item-actions button[aria-pressed="true"]:enabled,
.data-item-list-item-actions button[aria-pressed="true"]:enabled {
  background-color: var(--primary-container);
}
.data-item-actions button[aria-pressed="true"]:enabled path,
.data-item-list-item-actions button[aria-pressed="true"]:enabled path {
  fill: var(--on-primary-container);
}
.data-item-actions button[aria-pressed="true"]:enabled:hover,
.data-item-list-item-actions button[aria-pressed="true"]:enabled:hover {
  background-color: color-mix(
    in srgb, var(--on-primary-container) 8%, var(--primary-container));
}
.data-item-list-item {
  background-color: var(--surface-container-high);
  color: var(--on-surface);
}
.data-item-list-item:hover {
  background-color: color-mix(
    in srgb, var(--on-surface) 8%, var(--surface-container-high));
}
.data-item-list-item.selected {
  background-color: var(--secondary-container);
  color: var(--on-secondary-container);
}
.data-item-list-item.selected:hover {
  background-color: color-mix(
    in srgb, var(--on-secondary-container) 8%, var(--secondary-container));
}
.data-item-list-item-content {
  background-color: transparent;
  color: inherit;
}
.data-item-list-item-content:enabled path {
  fill: currentColor;
}
.data-item-list-empty,
.data-item-list-item-details dt {
  color: var(--on-surface-variant);
}
.data-item-list-item-details {
  border-color: var(--outline);
}

/* snackbar */
.snackbar {
  background-color: var(--inverse-surface);
  color: var(--inverse-on-surface);
}

/* modal dialog */
.modal {
  .modal-content {
    background-color: var(--surface-container);
    color: var(--on-surface);
  }
  .modal-content-scroll {
    background-color: var(--surface-container-high);

    th {
      background-color: var(--primary);
      color: var(--on-primary);
      border-color: var(--outline);
    }
    td {
      border-color: var(--surface-container);
    }
    tbody tr:nth-child(even) {
      background-color: var(--surface-container);
    }
    tbody tr:hover {
      background-color: var(--primary-container);
      color: var(--on-primary-container);
    }
  }
}
