import {getDwvVersion} from 'dwv';
import {startApp} from './applauncher.js';
import {getDropboxElement} from './lib/dropboxLoader.js';
import {getRightPanelElements} from './lib/rightPanel.js';
import {getModalElement} from './lib/modal.js';

import styles from './dwv-component.css';
import themeCommon from './theme/common.css';
import themeDark from './theme/dark.css';
import themeLight from './theme/light.css';
import themeBlue from './theme/blue.css';
import themePink from './theme/pink.css';

/**
 * @import {DwvAppService} from './lib/dwvAppService.js';
 */

/**
 * Split a white space separated attribute value into a list of
 * non empty strings.
 *
 * @param {string} value The attribute value.
 * @returns {string[]} The list of values.
 */
export function splitAttribute(value) {
  return value.split(/\s+/).filter((item) => item !== '');
}

/**
 * DWV component: display DICOM data using DWV (DICOM Web Viewer).
 * Possible attributes are:
 * - uri: an input string URI to load the data from,
 * - urls: white space separated list of urls to load the data from,
 * - loadfromwindowlocation: (boolean) use the window location
 *   as input uri if it contains search arguments,
 * - showlegend: (boolean) show or not the legend (defaults to false),
 * - wlpresetname, wlpresetcenter and wlpresetwidth: start
 *   the viewer with a specific window level setting instead of the one
 *   present in the DICOM file (only applied if all three values are present),
 * - height: the css height of the component,
 * - width: the css width of the component,
 * - tools: white space separated list of viewer tools, available are:
 *   'Scroll', 'ZoomAndPan', 'WindowLevel' and 'Draw' (case insensitive).
 * - theme: one or two theme names (white space separated), if two are
 *   provided, the first one will be used as light theme and the second
 *   one as dark.
 *   Available: 'light','dark', 'blue' (light) and 'pink' (dark),
 *   defaults to 'light dark'.
 *
 * Attributes are case insensitive. Boolean type are considered true if
 * present whatever the value. Attributes are read when the element is
 * first connected to the document, later changes are ignored.
 *
 * The viewer is released when the element is removed from the document
 * (but not when it is moved within it).
 *
 * A dropbox is shown if no uri nor urls are provided. It allows to
 * manually load dicom data from the local system.
 *
 * The inner div structure is:
 * ```
 * <div class='dwv'>
 *   <div class='header'></div>
 *   <div class='content'>
 *     <div class='layerGroup'></div>
 *     <aside class='right-panel'></aside>
 *   </div>
 *   <div class='footer'></div>
 * </div>
 * ```
 * Each div css is overridable via `dwv-simple::part(dwv)` (replace `dwv`
 * by the desired div class name).
 *
 * The component renders in a shadow root without slot: children of the
 * `dwv-simple` element are not displayed.
 *
 * Ref:
 * - {@link https://developer.mozilla.org/en-US/docs/Web/API/Web_components},
 * - {@link https://github.com/ivmartel/dwv}.
 *
 * @example
 * <dwv-simple></dwv-simple>
 * @example
 * <dwv-simple showlegend loadfromwindowlocation></dwv-simple>
 * @example
 * <dwv-simple showlegend loadfromwindowlocation theme="blue"></dwv-simple>
 * @example
 * <dwv-simple
 *   uri="https://www.demo.com/index.html?input=file.dcm"
 * ></dwv-simple>
 * @example
 * <dwv-simple
 *   urls="
 *     https://raw.githubusercontent.com/ivmartel/dwv/master/tests/data/bbmri-53323851.dcm
 *     https://raw.githubusercontent.com/ivmartel/dwv/master/tests/data/bbmri-53323707.dcm
 *   "
 * ></dwv-simple>
 * @example
 * <dwv-simple
 *   urls="
 *     https://raw.githubusercontent.com/ivmartel/dwv/master/tests/data/bbmri-53323851.dcm
 *     https://raw.githubusercontent.com/ivmartel/dwv/master/tests/data/bbmri-53323707.dcm
 *   "
 *   wlpresetname="preset0"
 *   wlpresetcenter="0"
 *   wlpresetwidth="2500"
 * ></dwv-simple>
 * @example
 * <dwv-simple
 *   urls="
 *     https://raw.githubusercontent.com/ivmartel/dwv/master/tests/data/bbmri-53323851.dcm
 *     https://raw.githubusercontent.com/ivmartel/dwv/master/tests/data/bbmri-53323707.dcm
 *   "
 *   tools="scroll windowlevel"
 * ></dwv-simple>
 */
export class DwvComponent extends HTMLElement {
  /**
   * The dwv app service, defined while the viewer is running.
   *
   * @type {DwvAppService|undefined}
   */
  #dwvAppService;

  constructor() {
    // Always call super first in constructor
    super();
    this.attachShadow({mode: 'open'});
  }

  /**
   * Invoked each time the custom element is connected to the document's DOM.
   */
  connectedCallback() {
    // already running: the element was moved
    if (typeof this.#dwvAppService !== 'undefined') {
      return;
    }

    // use element id as viewer id if present or
    // generate random (starting with a letter to be a proper html id)
    let viewerId;
    if (this.hasAttribute('id')) {
      viewerId = this.getAttribute('id');
    } else {
      const letters = 'abcdefghijklmnopqrstuvwxyz';
      const letterIndex =
        window.crypto.getRandomValues(new Uint8Array(1))[0] % letters.length;
      viewerId = letters[letterIndex] +
        window.crypto.randomUUID().substring(0, 8);
    }

    // main container
    const container = document.createElement('div');
    container.id = viewerId + '-dwv';
    container.className = 'dwv';
    container.part = 'dwv';

    // fill container
    container.appendChild(this.#getHeader(viewerId));
    container.appendChild(this.#getContent(viewerId));
    if (this.hasAttribute('showlegend')) {
      container.appendChild(this.#getFooter());
    }
    container.appendChild(this.#getExtra(viewerId));

    // extra css for height and width
    let extraCss = '';
    if (this.hasAttribute('height')) {
      extraCss += 'height: ' + this.getAttribute('height') + ';';
    } else {
      extraCss += 'height: 90%;';
    }
    if (this.hasAttribute('width')) {
      extraCss += 'width: ' + this.getAttribute('width') + ';';
    }
    // style
    const styleElement = document.createElement('style');
    styleElement.innerHTML += '.dwv {' + extraCss + '}\n\n';
    styleElement.innerHTML += styles.toString();

    // theme
    const availableThemes = {
      light: themeLight,
      dark: themeDark,
      blue: themeBlue,
      pink: themePink
    };
    let themes = ['light', 'dark'];
    if (this.hasAttribute('theme')) {
      // keep first 2
      let inputThemes = splitAttribute(this.getAttribute('theme')).slice(0, 2);
      // keep valid
      inputThemes = inputThemes.filter((item) => {
        return typeof availableThemes[item] !== 'undefined';
      });
      if (inputThemes.length !== 0) {
        themes = inputThemes;
      }
    }
    // use media preference when 2 themes
    if (themes.length === 2) {
      styleElement.innerHTML += '@media (prefers-color-scheme: light) {';
      styleElement.innerHTML += availableThemes[themes[0]].toString();
      styleElement.innerHTML += '}';
      styleElement.innerHTML += '@media (prefers-color-scheme: dark) {';
      styleElement.innerHTML += availableThemes[themes[1]].toString();
      styleElement.innerHTML += '}';
    } else {
      styleElement.innerHTML += availableThemes[themes[0]].toString();
    }
    styleElement.innerHTML += themeCommon.toString();

    // shadow root
    this.shadowRoot.replaceChildren(styleElement, container);

    // create options from attributes
    const options = {};
    // load
    if (this.hasAttribute('uri')) {
      options.uri = this.getAttribute('uri');
    } else if (this.hasAttribute('urls')) {
      options.urls = splitAttribute(this.getAttribute('urls'));
    } else if (this.hasAttribute('loadfromwindowlocation')) {
      if (window.location.search !== '') {
        options.uri = window.location.href;
      }
    }
    // window level
    if (this.hasAttribute('wlpresetname') &&
      this.hasAttribute('wlpresetcenter') &&
      this.hasAttribute('wlpresetwidth')) {
      options.wlpreset = {
        name: this.getAttribute('wlpresetname'),
        center: this.getAttribute('wlpresetcenter'),
        width: this.getAttribute('wlpresetwidth')
      };
    }
    // tools
    if (this.hasAttribute('tools')) {
      options.tools = splitAttribute(this.getAttribute('tools'));
    }

    // start app
    this.#dwvAppService = startApp(viewerId, options, this.shadowRoot);
  }

  /**
   * Invoked each time the custom element is disconnected from the
   * document's DOM.
   */
  disconnectedCallback() {
    // a move disconnects and reconnects the element synchronously:
    // only release the viewer if it is still disconnected afterwards
    queueMicrotask(() => {
      if (!this.isConnected && typeof this.#dwvAppService !== 'undefined') {
        this.#dwvAppService.dispose();
        this.#dwvAppService = undefined;
        this.shadowRoot.replaceChildren();
      }
    });
  }

  /**
   * Get the HTML header element.
   *
   * @param {string} viewerId The viewer id.
   * @returns {HTMLElement} The element.
   */
  #getHeader(viewerId) {
    const header = document.createElement('div');
    header.id = viewerId + '-header';
    header.className = 'header';
    header.part = 'header';

    return header;
  }

  /**
   * Get the HTML content element.
   *
   * @param {string} viewerId The viewer id.
   * @returns {HTMLElement} The element.
   */
  #getContent(viewerId) {
    // layer group
    const layerGroup = document.createElement('div');
    layerGroup.id = viewerId + '-layerGroup';
    layerGroup.className = 'layerGroup';
    layerGroup.part = 'layerGroup';
    // drop box
    const dropBox = getDropboxElement(viewerId);
    layerGroup.appendChild(dropBox);

    // main content div
    const content = document.createElement('div');
    content.className = 'content';
    content.part = 'content';
    content.appendChild(layerGroup);

    // right panel
    const panelElements = getRightPanelElements(viewerId);
    content.appendChild(panelElements[0]);
    content.appendChild(panelElements[1]);

    return content;
  }

  /**
   * Get the HTML footer element.
   *
   * @returns {HTMLElement} The element.
   */
  #getFooter() {
    const dwvLink = document.createElement('a');
    dwvLink.href = 'https://github.com/ivmartel/dwv';
    dwvLink.title = 'dwv on github';
    dwvLink.appendChild(document.createTextNode('dwv'));

    const para = document.createElement('p');
    para.appendChild(document.createTextNode('Powered by '));
    para.appendChild(dwvLink);
    para.appendChild(document.createTextNode(
      ' ' + getDwvVersion() + '.'));

    const footer = document.createElement('div');
    footer.className = 'footer';
    footer.part = 'footer';
    footer.appendChild(para);

    return footer;
  }

  /**
   * Get extra element.
   *
   * @param {string} viewerId The viewer id.
   * @returns {HTMLElement} The element.
   */
  #getExtra(viewerId) {
    const modal = getModalElement(viewerId);
    return modal;
  }
}

// Define the new element
// https://developer.mozilla.org/en-US/docs/Web/API/Window/customElements
customElements.define('dwv-simple', DwvComponent);
