:host {
  /* surface: main background */
  --surface: #faf9fd;
  /* text and icons on any surface */
  --on-surface: #1a1b1f;
  /* surface container: panels, dialogs */
  --surface-container: #efedf0;
  /* surface container high: elements on top of surface container */
  --surface-container-high: #e9e7eb;
  /* primary: buttons */
  --primary: #005cbb;
  --on-primary: #fefefe;
  /* primary container: selected buttons, pressed toggles */
  --primary-container: #d7e3ff;
  --on-primary-container: #00458f;
  /* secondary container: selected list items */
  --secondary-container: #dae2f9;
  --on-secondary-container: #131c2b;
  /* on surface variant: secondary text */
  --on-surface-variant: #44474f;
  /* inverse surface: snackbar */
  --inverse-surface: #2f3033;
  --inverse-on-surface: #f1f0f4;
  /* outline: borders */
  --outline: #74777f;
  /* outline variant: decorative borders (panel) */
  --outline-variant: #c4c6d0;
}
